// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {GovernorUpgradeable} from "contracts/extensions/GovernorUpgradeable.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {Time} from "@openzeppelin/contracts/utils/types/Time.sol";
import {IComp} from "contracts/interfaces/IComp.sol";

/// @title GovernorVotesCompUpgradeable
/// @author [ScopeLift](https://scopelift.co)
/// @notice Modified GovernorVotes contract that supports Compound's COMP token.
/// @custom:security-contact security@compound.finance
abstract contract GovernorVotesCompUpgradeable is Initializable, GovernorUpgradeable {
    /// @custom:storage-location erc7201:storage.GovernorVotesComp
    struct GovernorVotesCompStorage {
        IComp _token;
    }

    // keccak256(abi.encode(uint256(keccak256("storage.GovernorVotesComp")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant GovernorVotesCompStorageLocation =
        0x2130f92f3b57a0ca0ff53b681825494ca70980d3b0ddffac97113db00028b600;

    function _getGovernorVotesCompStorage() private pure returns (GovernorVotesCompStorage storage $) {
        assembly {
            $.slot := GovernorVotesCompStorageLocation
        }
    }

    function __GovernorVotesComp_init(IComp _tokenAddress) internal onlyInitializing {
        __GovernorVotesComp_init_unchained(_tokenAddress);
    }

    function __GovernorVotesComp_init_unchained(IComp _tokenAddress) internal onlyInitializing {
        GovernorVotesCompStorage storage $ = _getGovernorVotesCompStorage();
        $._token = _tokenAddress;
    }

    /// @notice Returns the IComp token used for governance.
    /// @dev This function retrieves the token address from the contract's storage.
    /// @return IComp The COMP token interface used for governance voting.
    function token() public view virtual returns (IComp) {
        GovernorVotesCompStorage storage $ = _getGovernorVotesCompStorage();
        return $._token;
    }

    /// @notice This function implements the clock interface as specified in ERC-6372.
    /// @dev Returns the current clock value used for governance voting.
    /// @return uint48 The current block number cast to uint48.
    function clock() public view virtual override returns (uint48) {
        return Time.blockNumber();
    }

    /// @notice Returns a machine-readable description of the clock as specified in ERC-6372.
    /// @dev This function provides information about the clock mode used for governance timing.
    /// @return string A string describing the clock mode, indicating that block numbers are used
    ///         as the time measure, with the default starting point.
    function CLOCK_MODE() public view virtual override returns (string memory) {
        return "mode=blocknumber&from=default";
    }

    /// @notice Retrieves the voting weight for a specific account at a given timepoint.
    /// @dev This function overrides the base _getVotes function to use Compound's getPriorVotes mechanism.
    /// @param _account The address of the account to check the voting weight for.
    /// @param _timepoint The timepoint at which to check the voting weight.
    /// @param /*params*/ Unused parameter, kept for compatibility with the base function signature.
    /// @return uint256 The voting weight of the account at the specified timepoint.
    function _getVotes(address _account, uint256 _timepoint, bytes memory /*params*/ )
        internal
        view
        virtual
        override
        returns (uint256)
    {
        return token().getPriorVotes(_account, _timepoint);
    }
}

contracts/extensions/GovernorSettableFix.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {GovernorUpgradeable} from "contracts/extensions/GovernorUpgradeable.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {Checkpoints} from "@openzeppelin/contracts/utils/structs/Checkpoints.sol";

/// @title GovernorSettableFixedQuorumUpdateable
/// @author [ScopeLift](https://scopelift.co)
/// @notice An abstract extension to the Governor which implements a fixed quorum which can be updated by governance.
/// @custom:security-contact security@compound.finance
abstract contract GovernorSettableFixedQuorumUpgradeable is Initializable, GovernorUpgradeable {
    using Checkpoints for Checkpoints.Trace208;

    /// @custom:storage-location erc7201:storage.GovernorSettableFixedQuorum
    struct GovernorSettableFixedQuorumStorage {
        Checkpoints.Trace208 _quorumCheckpoints;
    }

    // keccak256(abi.encode(uint256(keccak256("storage.GovernorSettableFixedQuorum")) - 1)) &
    // ~bytes32(uint256(0xff))
    bytes32 private constant GovernorSettableFixedQuorumStorageLocation =
        0xfc13b0622f15c0c6558fbb10a1f5d36853f903c871b669bae7001d348b50ca00;

    function _getGovernorSettableFixedQuorumStorage()
        private
        pure
        returns (GovernorSettableFixedQuorumStorage storage $)
    {
        assembly {
            $.slot := GovernorSettableFixedQuorumStorageLocation
        }
    }

    /// @notice Emitted when the quorum value has changed.
    event QuorumUpdated(uint256 oldQuorum, uint256 newQuorum);

    function __GovernorSettableFixedQuorum_init(uint256 _initialQuorum) internal onlyInitializing {
        __GovernorSettableFixedQuorum_init_unchained(_initialQuorum);
    }

    function __GovernorSettableFixedQuorum_init_unchained(uint256 _initialQuorum) internal onlyInitializing {
        _setQuorum(_initialQuorum);
    }

    /// @notice A function to set quorum for the current timepoint. Proposals created after this timepoint will be
    /// subject to the new quorum.
    /// @param _amount The new quorum threshold.
    function setQuorum(uint256 _amount) external virtual onlyGovernance {
        _setQuorum(_amount);
    }

    /// @notice A function to get the quorum threshold for a given timepoint.
    /// @param _voteStart The vote start timepoint for a given proposal.
    function quorum(uint256 _voteStart) public view virtual override returns (uint256) {
        GovernorSettableFixedQuorumStorage storage $ = _getGovernorSettableFixedQuorumStorage();
        return $._quorumCheckpoints.upperLookupRecent(SafeCast.toUint32(_voteStart));
    }

    /// @notice A function to set quorum for the current timepoint.
    /// @param _amount The quorum amount to checkpoint.
    function _setQuorum(uint256 _amount) internal virtual {
        uint48 _timepoint = clock();
        GovernorSettableFixedQuorumStorage storage $ = _getGovernorSettableFixedQuorumStorage();
        emit QuorumUpdated(quorum(_timepoint), _amount);
        $._quorumCheckpoints.push(_timepoint, SafeCast.toUint208(_amount));
    }
}

